window.__UBCA_CORRECTIONS__ = [{"date": "2026-09-17", "caseId": "patrick-warren-sr", "text": "New case added to the archive: Patrick Warren Sr. (Killeen, Texas, 2021), sourced from KWTX, Law & Crime, and KXXV."}, {"date": "2026-09-17", "caseId": "paul-oneal", "text": "New case added to the archive: Paul O'Neal (Chicago, Illinois, 2016), sourced from the Chicago Tribune and CBS News Chicago."}, {"date": "2026-09-17", "caseId": "jaheim-mcmillan", "text": "New case added to the archive: Jaheim McMillan (Gulfport, Mississippi, 2022), sourced from the Mississippi Free Press, WLOX, and Newsweek."}, {"date": "2026-09-17", "caseId": "xzavier-hill", "text": "New case added to the archive: Xzavier Hill (Goochland County, Virginia, 2021), sourced from Newsweek, WRIC (ABC 8News), and VPM."}, {"date": "2026-09-17", "caseId": "tyrea-pryor", "text": "New case added to the archive: Tyrea Pryor (Independence, Missouri, 2022), sourced from KCUR, NBC News, and the Kansas City Star (via AOL News)."}, {"date": "2026-09-17", "caseId": "donnie-sanders", "text": "New case added to the archive: Donnie Sanders (Kansas City, Missouri, 2020), whose case is connected to a later, well-documented pattern of the same officer going on to kill two more people. Sourced from CNN, KCUR, and NBC News."}, {"date": "2026-09-17", "caseId": "damian-daniels", "text": "New case added to the archive: Damian Daniels (San Antonio, Texas, 2020), sourced from KSAT, the San Antonio Report, and Newsweek."}, {"date": "2026-09-17", "caseId": "kevin-peterson-jr", "text": "New case added to the archive: Kevin Peterson Jr. (Vancouver, Washington, 2020), sourced from OPB, KATU, and FOX 13 Seattle."}, {"date": "2026-09-17", "caseId": "roshad-mcintosh", "text": "New case added to the archive: Roshad McIntosh (Chicago, Illinois, 2014), sourced from the Chicago Sun-Times, CNN, and the People's Law Office's press release on the family's federal lawsuit."}, {"date": "2026-09-17", "caseId": "frank-tyson", "text": "New case added to the archive: Frank Tyson (Canton, Ohio, 2024), sourced from CBS News, Ideastream Public Media, and Yahoo News/The Repository's coverage of the August 2026 plea deals."}, {"date": "2026-09-17", "caseId": "colfax-massacre", "text": "New case added to the archive: The Colfax Massacre (Colfax, Louisiana, 1873), the deadliest single incident of racial violence during Reconstruction, whose resulting Supreme Court case (United States v. Cruikshank) overturned real convictions and curtailed federal civil rights enforcement for decades. Sourced from BlackPast.org, 64 Parishes, and the Supreme Court Historical Society."}, {"date": "2026-09-15", "caseId": "bunk-richardson", "text": "New case added to the archive: Bunk Richardson (Gadsden, Alabama, 1906), lynched despite never being charged with any crime. Sourced from the Equal Justice Initiative's own account, AL.com, and The Gadsden Times."}, {"date": "2026-09-15", "caseId": "dexter-reed", "text": "New case added to the archive: Dexter Reed (Chicago, Illinois, 2024). Sourced from WTTW, the Chicago Sun-Times, and Courthouse News Service's coverage of the August 2025 charging decision."}, {"date": "2026-09-15", "caseId": "allen-brooks", "text": "New case added to the archive: Allen Brooks (Dallas, Texas, 1910). Sourced from The New York Times, KERA News, and CBS News Texas."}, {"date": "2026-09-15", "caseId": "mary-and-hayes-turner", "text": "New case added to the archive: Mary Turner & Hayes Turner (Brooks County, Georgia, 1918), whose deaths directly prompted the 1922 Dyer Anti-Lynching Bill. Sourced from BlackPast.org, the Equal Justice Initiative, and Wikipedia's citation trail."}, {"date": "2026-09-15", "caseId": "james-lanier", "text": "New case added to the archive: James Lanier (Wallace, North Carolina, 2023), sourced from WITN, FOX8 WGHP, and Emancipate North Carolina."}, {"date": "2026-09-15", "caseId": "darryl-tyree-williams", "text": "New case added to the archive: Darryl Tyree Williams (Raleigh, North Carolina, 2023), sourced from ABC11 Raleigh-Durham, WRAL, and WUNC's coverage of the December 2025 settlement."}, {"date": "2026-09-15", "caseId": "kemonte-cobbs", "text": "New case added to the archive: Kemonte Cobbs (Gary, Indiana, 2017), sourced from The Times of Northwest Indiana and the Chicago Tribune/Post-Tribune."}, {"date": "2026-09-15", "caseId": "david-jones", "text": "New case added to the archive: David Jones (Philadelphia, Pennsylvania, 2017), sourced from The Philadelphia Inquirer, WHYY, and the City of Philadelphia's Citizens Police Oversight Commission."}, {"date": "2026-09-15", "caseId": "shipp-and-smith", "text": "New case added to the archive: Thomas Shipp & Abram Smith (Marion, Indiana, 1930), whose lynching produced the most widely reproduced lynching photograph in American history and directly inspired \u201cStrange Fruit.\u201d Sourced from NPR and the Indiana Historical Bureau's own history blog and America's Black Holocaust Museum."}, {"date": "2026-09-15", "caseId": "ricky-cobb-ii", "text": "New case added to the archive: Ricky Cobb II (Minneapolis, Minnesota, 2023), sourced from Wikipedia's citation trail, CBS News Minnesota, and the Star Tribune."}, {"date": "2026-09-15", "caseId": "luke-stewart", "text": "New case added to the archive: Luke Stewart (Euclid, Ohio, 2017), sourced from News 5 Cleveland's coverage of both the grand jury decision and the 2022 civil verdict, and the ACLU of Ohio."}, {"date": "2026-09-15", "caseId": "jalen-randle", "text": "New case added to the archive: Jalen Randle (Houston, Texas, 2022), sourced from Houston Public Media, KHOU 11, and ABC13 Houston."}, {"date": "2026-09-15", "caseId": "daquain-johnson", "text": "New case added to the archive: Da'Quain Johnson (Grand Rapids, Michigan, 2026), sourced from Wikipedia's citation trail, The Trace, and FOX 17 West Michigan."}, {"date": "2026-09-15", "caseId": "najee-seabrooks", "text": "New case added to the archive: Najee Seabrooks (Paterson, New Jersey, 2023), sourced from the New Jersey Monitor, CNN, and AP/Yahoo News's coverage of the released body camera footage."}, {"date": "2026-09-15", "caseId": "trayvon-martin", "text": "Classification correction: introduced a new status, \u201cUnresolved \u2014 No Conviction,\u201d distinct from \u201cUnsolved.\u201d Trayvon Martin's case was reclassified from Unsolved to this new status, since George Zimmerman was in fact charged and tried, and a jury reached a verdict (acquittal) \u2014 unlike the majority of cases in this archive, where no charges were ever filed. The underlying facts are unchanged: the medical examiner's homicide finding stands, and no one has ever been convicted in Martin's death. This correction was prompted by a reader."}, {"date": "2026-09-08", "caseId": "frederick-cox-jr", "text": "New case added to the archive: Frederick Cox Jr. (High Point, North Carolina, 2020), sourced from WFMY News 2 and FOX8 WGHP's coverage of both the grand jury decision and the 2025 settlement."}, {"date": "2026-09-08", "caseId": "winston-smith-jr", "text": "New case added to the archive: Winston Boogie Smith Jr. (Minneapolis, Minnesota, 2021), sourced from NPR, NBC News, and the Star Tribune."}, {"date": "2026-09-08", "caseId": "moores-ford-lynchings", "text": "New case added to the archive: the Moore's Ford lynchings \u2014 Roger Malcom, Dorothy Malcom, George Dorsey & Mae Murray Dorsey (Monroe, Georgia, 1946), known as \u201cthe last mass lynching in America.\u201d Sourced from the Southern Poverty Law Center, Wikipedia's citation trail, and NBC News."}, {"date": "2026-09-08", "caseId": "omar-edwards", "text": "New case added to the archive: Omar Edwards (New York, New York, 2009), sourced from NBC News and TheGrio."}, {"date": "2026-09-08", "caseId": "deandre-brunston", "text": "New case added to the archive: Deandre Brunston (Compton, California, 2003), sourced from Wikipedia's citation trail, the San Francisco Chronicle, and the Fatal Encounters database."}, {"date": "2026-09-08", "caseId": "trey-pringle", "text": "New case added to the archive: Trey Pringle (Seabrook, South Carolina, 2018), sourced from WTOC, WSAV, and FITSNews's coverage of the chokehold allegation."}, {"date": "2026-09-08", "caseId": "jeremy-mcdole", "text": "New case added to the archive: Jeremy McDole (Wilmington, Delaware, 2015), sourced from Wikipedia's citation trail, 6abc Philadelphia, and CBS News Philadelphia."}, {"date": "2026-09-08", "caseId": "joshua-ruffin", "text": "New case added to the archive: Joshua Ruffin (Columbia, South Carolina, 2020), sourced from The Post and Courier, WIS10, and AP/WLOS."}, {"date": "2026-09-08", "caseId": "decynthia-clements", "text": "New case added to the archive: DeCynthia Clements (Elgin, Illinois, 2018), sourced from CNN, the Daily Herald, and Romanucci & Blandin's press release on the family's federal lawsuit."}, {"date": "2026-09-08", "caseId": "kenneth-ross-jr", "text": "New case added to the archive: Kenneth Ross Jr. (Gardena, California, 2018), sourced from the LA County DA's own Justice System Integrity Division report, ABC7 Los Angeles, and NBC News."}, {"date": "2026-09-08", "caseId": "linus-phillip", "text": "New case added to the archive: Linus Phillip (Largo, Florida, 2018), sourced from the Tampa Bay Times, CBS News, and WFLA."}, {"date": "2026-09-08", "caseId": "omari-cryer", "text": "New case added to the archive: Omari Cryer (Louisville, Kentucky, 2022), sourced from Louisville Public Media, WAVE 3 News, and WHAS11."}, {"date": "2026-09-08", "caseId": "jordell-richardson", "text": "New case added to the archive: Jor'Dell Richardson (Aurora, Colorado, 2023), sourced from CPR News, CBS News Colorado, and 9NEWS (KUSA)."}, {"date": "2026-09-08", "caseId": "christopher-deandre-mitchell", "text": "New case added to the archive: Christopher DeAndre Mitchell (Torrance, California, 2018), sourced from the LA County District Attorney's own statement, NBC Los Angeles, and FOX 11 Los Angeles's coverage of the April 2026 dismissal."}, {"date": "2026-09-08", "caseId": "anthony-lowe-jr", "text": "New case added to the archive: Anthony Lowe Jr. (Huntington Park, California, 2023), sourced from the Los Angeles County District Attorney's own statement, Police1, and ABC7 Los Angeles."}, {"date": "2026-09-08", "caseId": "william-green", "text": "New case added to the archive: William Green (Landover, Maryland, 2020), sourced from The Washington Post, WUSA9, and the AFRO American Newspapers' coverage of the December 2023 acquittal."}, {"date": "2026-08-31", "caseId": "vincent-truitt", "text": "New case added to the archive: Vincent Truitt (Marietta, Georgia, 2020), sourced from WSB-TV, 11Alive, and 13WMAZ's coverage of the dismissed federal lawsuit."}, {"date": "2026-08-31", "caseId": "oshae-terry", "text": "New case added to the archive: O'Shae Terry (Arlington, Texas, 2018), sourced from KERA News, Reason, and WFAA's coverage of the 2023 deferred-adjudication plea."}, {"date": "2026-08-31", "caseId": "robert-lawrence-white", "text": "New case added to the archive: Robert Lawrence White (Silver Spring, Maryland, 2018), sourced from The Washington Post, WTOP News, and CourtListener's record of the dismissed federal lawsuit."}, {"date": "2026-08-31", "caseId": "charly-keunang", "text": "New case added to the archive: Charly \u201cAfrica\u201d Keunang (Los Angeles, California, 2015), sourced from LAist, CBS Los Angeles, and CBC News."}, {"date": "2026-08-31", "caseId": "yvette-smith", "text": "New case added to the archive: Yvette Smith (Camp Swift, Texas, 2014), sourced from the Austin American-Statesman, KXAN, and Fox 7 Austin."}, {"date": "2026-08-31", "caseId": "delrawn-small", "text": "New case added to the archive, bringing the total to 200 cases: Delrawn Small (Brooklyn, New York, 2016), sourced from ABC7 New York, NBC New York, and the NAACP Legal Defense Fund."}, {"date": "2026-08-31", "caseId": "aaron-bailey", "text": "New case added to the archive: Aaron Bailey (Indianapolis, Indiana, 2017), sourced from WTHR, Fox 59, and the Indianapolis Recorder."}, {"date": "2026-08-31", "caseId": "sahleem-tindle", "text": "New case added to the archive: Sahleem Tindle (Oakland, California, 2018), sourced from the San Francisco Chronicle, East Bay Express, and NBC Bay Area's coverage of the 2020 civil verdict."}, {"date": "2026-08-31", "caseId": "miles-jackson", "text": "New case added to the archive: Miles Jackson (Westerville, Ohio, 2021), sourced from 10TV (WBNS), AP/CBS News Pittsburgh, and the Franklin County Prosecutor's Office's own statement."}, {"date": "2026-08-31", "caseId": "charleena-lyles", "text": "New case added to the archive: Charleena Lyles (Seattle, Washington, 2017), sourced from The Seattle Times, KIRO 7, and KING 5."}, {"date": "2026-08-31", "caseId": "george-tillman", "text": "New case added to the archive: George Tillman III (South Ozone Park, New York, 2016), sourced from QNS, DNAinfo, and Jurimatic's coverage of the 2025 civil verdict."}, {"date": "2026-08-31", "caseId": "thurman-blevins", "text": "New case added to the archive: Thurman Blevins (Minneapolis, Minnesota, 2018), sourced from the Star Tribune, MPR News, and PBS NewsHour."}, {"date": "2026-08-31", "caseId": "christopher-whitfield", "text": "New case added to the archive: Christopher Whitfield (Ethel, Louisiana, 2019), sourced from The Advocate, The Washington Times/AP, and WBRZ."}, {"date": "2026-08-31", "caseId": "willie-tillman", "text": "New case added to the archive: Willie Tillman (Fayetteville, Arkansas, 2016), sourced from the Arkansas Democrat-Gazette and KNWA/FOX24."}, {"date": "2026-08-31", "caseId": "tommie-mcglothen-jr", "text": "New case added to the archive: Tommie McGlothen Jr. (Shreveport, Louisiana, 2020), sourced from KSLA, KTBS, and Yahoo News/AP."}, {"date": "2026-08-31", "caseId": "dejuan-guillory", "text": "New case added to the archive: DeJuan Guillory (Mamou, Louisiana, 2017), sourced from CNN, KLFY, and The Advocate."}, {"date": "2026-08-31", "caseId": "alteria-woods", "text": "New case added to the archive: Alteria Woods (Gifford, Florida, 2017), sourced from CBS12, WPTV, and Vero News's coverage of the grand jury and the 2021 trial."}, {"date": "2026-08-31", "caseId": "mickel-lewis-sr", "text": "New case added to the archive: Mickel Lewis Sr. (Mojave, California, 2020), sourced from KGET 17 News and the Davis Vanguard's coverage of the 2025 civil verdict."}, {"date": "2026-08-31", "caseId": "deon-kay", "text": "New case added to the archive: Deon Kay (Washington, D.C., 2020), sourced from The Washington Post, WUSA9, and The Washington Informer's coverage of the 2026 settlement."}, {"date": "2026-08-31", "caseId": "natasha-mckenna", "text": "New case added to the archive: Natasha McKenna (Fairfax, Virginia, 2015), a jail in-custody death, sourced from Wikipedia's citation trail, WAMU, and WTOP News."}, {"date": "2026-08-31", "caseId": "jamycheal-mitchell", "text": "New case added to the archive: Jamycheal Mitchell (Portsmouth, Virginia, 2015), a jail in-custody death, sourced from the ACLU, WAVY, and 13News Now (WVEC)."}, {"date": "2026-08-31", "caseId": "marvin-scott-iii", "text": "New case added to the archive: Marvin Scott III (McKinney, Texas, 2021), a jail in-custody death, sourced from The Texas Tribune, CNN, and CBS News Texas."}, {"date": "2026-08-31", "caseId": "michael-dean", "text": "New case added to the archive: Michael Dean (Temple, Texas, 2019), sourced from KWTX and 6 News (KCEN)'s coverage of the 2023 acquittal and the ongoing civil lawsuit."}, {"date": "2026-08-31", "caseId": "byron-williams", "text": "New case added to the archive: Byron Williams (Las Vegas, Nevada, 2019), sourced from the Las Vegas Review-Journal, Nevada Current, and Courthouse News Service's coverage of the 2024 civil ruling."}, {"date": "2026-08-31", "caseId": "walter-wallace-jr", "text": "New case added to the archive: Walter Wallace Jr. (Philadelphia, Pennsylvania, 2020), sourced from The Philadelphia Inquirer's coverage of both his life and the 2021 settlement, and WHYY."}, {"date": "2026-08-31", "caseId": "kajuan-raye", "text": "New case added to the archive: Kajuan Raye (Chicago, Illinois, 2016), sourced from the Chicago Sun-Times and CBS News Chicago's coverage of the 2020 civil verdict."}, {"date": "2026-08-31", "caseId": "dreasjon-reed", "text": "New case added to the archive: Dreasjon \u201cSean\u201d Reed (Indianapolis, Indiana, 2020), sourced from NPR, the Indianapolis Recorder, and TheGrio."}, {"date": "2026-08-31", "caseId": "jamee-johnson", "text": "New case added to the archive: Jamee Johnson (Jacksonville, Florida, 2019), sourced from News4Jax and First Coast News's coverage of both the family's lawsuit and the $200,000 settlement."}, {"date": "2026-08-31", "caseId": "terrence-sterling", "text": "New case added to the archive: Terrence Sterling (Washington, D.C., 2016), sourced from The Washington Post's coverage of both the federal declination and the internal MPD review, and WTOP News."}, {"date": "2026-08-31", "caseId": "crooms-and-pierce", "text": "New case added to the archive: Angelo Crooms & Sincere Pierce (Cocoa, Florida, 2020), sourced from Fox 35 Orlando, Click Orlando (WKMG), and Yahoo News/AP."}, {"date": "2026-08-31", "caseId": "antwon-rose-ii", "text": "New case added to the archive: Antwon Rose II (East Pittsburgh, Pennsylvania, 2018), sourced from Wikipedia's citation trail, CBS News Pittsburgh, and Pittsburgh's Public Source."}, {"date": "2026-08-31", "caseId": "devon-bailey", "text": "New case added to the archive: De'Von Bailey (Colorado Springs, Colorado, 2019), sourced from NBC News, Colorado Public Radio, and 9NEWS Denver's coverage of the 2022 settlement."}, {"date": "2026-08-31", "caseId": "steven-taylor", "text": "New case added to the archive: Steven Taylor (San Leandro, California, 2020), sourced from ABC7 San Francisco, the San Francisco Chronicle, and CBS News San Francisco's coverage of the December 2025 dismissal."}, {"date": "2026-08-31", "caseId": "kayla-moore", "text": "New case added to the archive: Kayla Moore (Berkeley, California, 2013), sourced from KQED, the San Francisco Chronicle, and Courthouse News Service."}, {"date": "2026-08-31", "caseId": "ej-bradford-jr", "text": "New case added to the archive: Emantic \u201cE.J.\u201d Bradford Jr. (Hoover, Alabama, 2018), sourced from the Alabama Attorney General's own report, NBC News, and CNN."}, {"date": "2026-08-27", "caseId": "julian-lewis", "text": "New case added to the archive: Julian Lewis (Sylvania, Georgia, 2020), sourced from Wikipedia's citation trail, WSAV-TV, and AP/Yahoo News's coverage of the federal review."}, {"date": "2026-08-27", "caseId": "osaze-osagie", "text": "New case added to the archive: Osaze Osagie (State College, Pennsylvania, 2019), sourced from Spotlight PA, WITF, and StateCollege.com's coverage of the dismissed federal lawsuit."}, {"date": "2026-08-27", "caseId": "chinedu-okobi", "text": "New case added to the archive: Chinedu Okobi (Millbrae, California, 2018), sourced from KQED, the San Francisco Chronicle, and coverage of the 2023 $4.5 million settlement."}, {"date": "2026-08-27", "caseId": "darius-tarver", "text": "New case added to the archive: Darius Tarver (Denton, Texas, 2020), sourced from The Dallas Morning News, Dallas Observer, and WFAA."}, {"date": "2026-08-27", "caseId": "alonzo-smith", "text": "New case added to the archive: Alonzo Smith (Washington, D.C., 2015), sourced from the DOJ/U.S. Attorney's Office's official statement, FOX 5 DC, and The Washington Post."}, {"date": "2026-08-27", "caseId": "ronald-greene", "text": "New case added to the archive: Ronald Greene (Monroe, Louisiana, 2019), sourced from CNN's coverage of both the 2024 dropped charges and the plea deal, and CBS News."}, {"date": "2026-08-27", "caseId": "john-neville", "text": "New case added to the archive: John Neville (Winston-Salem, North Carolina, 2019), sourced from NBC News, WFDD, and WFMY News 2's coverage of the charges against the nurse being dropped."}, {"date": "2026-08-27", "caseId": "tyre-king", "text": "New case added to the archive: Tyre King (Columbus, Ohio, 2016), sourced from CNN, Colorlines, and WOSU Public Media's coverage of the 2023 federal civil verdict."}, {"date": "2026-08-27", "caseId": "jonathan-sanders", "text": "New case added to the archive: Jonathan Sanders (Stonewall, Mississippi, 2015), sourced from Wikipedia's citation trail, the Southern Poverty Law Center, and Fox News/AP."}, {"date": "2026-08-27", "caseId": "miles-hall", "text": "New case added to the archive: Miles Hall (Walnut Creek, California, 2019), sourced from CNN, KTVU FOX 2, and SFBay."}, {"date": "2026-08-27", "caseId": "kendrec-mcdade", "text": "New case added to the archive: Kendrec McDade (Pasadena, California, 2012), sourced from NBC News, CBS Los Angeles, and the family's attorney's case summary."}, {"date": "2026-08-27", "caseId": "terrance-kellom", "text": "New case added to the archive: Terrance Kellom (Detroit, Michigan, 2015), sourced from CBS News, WXYZ Detroit's investigation into the officer's changed testimony, and The Detroit News."}, {"date": "2026-08-27", "caseId": "aura-rosser", "text": "New case added to the archive: Aura Rosser (Ann Arbor, Michigan, 2014), sourced from the ACLU of Michigan, The Michigan Daily, and AAIHS."}, {"date": "2026-08-27", "caseId": "aiyana-stanley-jones", "text": "New case added to the archive: Aiyana Stanley-Jones (Detroit, Michigan, 2010), sourced from The Detroit News, CBS News's coverage of both mistrials, and Reuters."}, {"date": "2026-08-27", "caseId": "andrew-brown-jr", "text": "New case added to the archive: Andrew Brown Jr. (Elizabeth City, North Carolina, 2021), sourced from NPR, ABC News, and The Washington Post."}, {"date": "2026-08-27", "caseId": "amir-locke", "text": "New case added to the archive: Amir Locke (Minneapolis, Minnesota, 2022), sourced from CBS News and Al Jazeera's coverage of both the charging decision and the family's lawsuit."}, {"date": "2026-08-27", "caseId": "rayshard-brooks", "text": "New case added to the archive: Rayshard Brooks (Atlanta, Georgia, 2020), sourced from NPR, CNN, and Wikipedia's citation trail."}, {"date": "2026-08-27", "caseId": "patrick-lyoya", "text": "New case added to the archive: Patrick Lyoya (Grand Rapids, Michigan, 2022), sourced from Michigan Advance, Wikipedia's citation trail, and WOOD TV8's coverage of the pending civil case."}, {"date": "2026-08-27", "caseId": "takiya-young", "text": "New case added to the archive: Ta'Kiya Young (Blendon Township, Ohio, 2023), sourced from AP News/NBC News, Wikipedia's citation trail, and The 19th/Capital B's coverage of the November 2025 acquittal."}, {"date": "2026-08-27", "caseId": "jayland-walker", "text": "New case added to the archive: Jayland Walker (Akron, Ohio, 2022), sourced from NPR, CNN, and PBS NewsHour's coverage of the settlement."}, {"date": "2026-08-27", "caseId": "india-kager", "text": "New case added to the archive: India Kager (Virginia Beach, Virginia, 2015), sourced from Amnesty International USA, WTKR, and 13News Now."}, {"date": "2026-08-27", "caseId": "alfred-olango", "text": "New case added to the archive: Alfred Olango (El Cajon, California, 2016), sourced from Wikipedia's citation trail, LAist, and 10News San Diego."}, {"date": "2026-08-27", "caseId": "jason-harrison", "text": "New case added to the archive: Jason Harrison (Dallas, Texas, 2014), sourced from ABC News, CNN, and the Dallas Morning News."}, {"date": "2026-08-27", "caseId": "jamar-clark", "text": "New case added to the archive: Jamar Clark (Minneapolis, Minnesota, 2015), sourced from NBC News, CNN, and BlackPast.org."}, {"date": "2026-08-27", "caseId": "jerame-reid", "text": "New case added to the archive: Jerame Reid (Bridgeton, New Jersey, 2014), sourced from the DOJ's own closing statement, Wikipedia's citation trail, and NBC10 Philadelphia."}, {"date": "2026-08-27", "caseId": "dontre-hamilton", "text": "New case added to the archive: Dontre Hamilton (Milwaukee, Wisconsin, 2014), sourced from NBC News's coverage of both the county and federal charging decisions, and Wikipedia's citation trail."}, {"date": "2026-08-27", "caseId": "stephon-watts", "text": "New case added to the archive: Stephon Watts (Calumet City, Illinois, 2012), sourced from NWI Times, the Chicago Reader, and HuffPost Chicago."}, {"date": "2026-08-27", "caseId": "mansur-ball-bey", "text": "New case added to the archive: Mansur Ball-Bey (St. Louis, Missouri, 2015), sourced from St. Louis Public Radio and KSDK's coverage of both the 2016 charging decision and the 2025 civil verdict."}, {"date": "2026-08-27", "caseId": "ronell-foster", "text": "New case added to the archive: Ronell Foster (Vallejo, California, 2018), sourced from ProPublica, the San Francisco Chronicle, and the Vallejo Sun. Linked in Case Connections to Willie McCoy \u2014 same officer, same department."}, {"date": "2026-08-27", "caseId": "marcus-david-peters", "text": "New case added to the archive: Marcus-David Peters (Richmond, Virginia, 2018), sourced from PBS NewsHour/AP, Richmond Magazine, and WRIC ABC 8News."}, {"date": "2026-08-27", "caseId": "willie-mccoy", "text": "New case added to the archive: Willie McCoy (Vallejo, California, 2019), sourced from NBC News, KTVU, and The Guardian's coverage of the officer's internal firing."}, {"date": "2026-08-27", "caseId": "legrier-and-jones", "text": "New case added to the archive: Quintonio LeGrier & Bettie Jones (Chicago, Illinois, 2015), sourced from NBC Chicago, ABC7 Chicago, and CBS Chicago."}, {"date": "2026-08-27", "caseId": "vonderrit-myers-jr", "text": "New case added to the archive: VonDerrit Myers Jr. (St. Louis, Missouri, 2014), sourced from St. Louis Public Radio, the St. Louis American, and CBS News."}, {"date": "2026-08-27", "caseId": "kajieme-powell", "text": "New case added to the archive: Kajieme Powell (St. Louis, Missouri, 2014), sourced from St. Louis Public Radio, St. Louis Magazine, and the St. Louis Post-Dispatch."}, {"date": "2026-08-27", "caseId": "christian-taylor", "text": "New case added to the archive: Christian Taylor (Arlington, Texas, 2015), sourced from BlackPast.org, NBC 5 Dallas-Fort Worth, and the National Police Accountability Project."}, {"date": "2026-08-27", "caseId": "anthony-lamar-smith", "text": "New case added to the archive: Anthony Lamar Smith (St. Louis, Missouri, 2011), sourced from NPR, CBS News, and BlackPast.org."}, {"date": "2026-08-27", "caseId": "clinton-avenue-five", "text": "New case added to the archive: The Clinton Avenue Five (Newark, New Jersey, 1978), a missing persons case, sourced from Wikipedia's citation trail, CBS News's coverage of the 2011 acquittal, and Local Talk Weekly's coverage of the 2025 civil appeal."}, {"date": "2026-08-27", "caseId": "pshara-jones", "text": "New case added to the archive: Pshara Marie Jones (Claremore, Oklahoma, 2015), a missing persons case, sourced from The Charley Project and a family-maintained case site."}, {"date": "2026-08-27", "caseId": "millbrook-twins", "text": "New case added to the archive: Dannette & Jeannette Millbrook (Augusta, Georgia, 1990), a missing persons case, sourced from Wikipedia's citation trail, NBC News/Dateline, and WFXG."}, {"date": "2026-08-27", "caseId": "barbara-dreher", "text": "New case added to the archive: Barbara Jean Dreher (Washington, D.C., 1984), a missing persons case, sourced from The Washington Post, The Charley Project, and The Deck podcast."}, {"date": "2026-08-27", "caseId": "tasha-wright", "text": "New case added to the archive: Tasha Shante Wright (Dallas, Texas, 1989), a missing persons case, sourced from The Charley Project, Solve the Case, and The Doe Network."}, {"date": "2026-08-27", "caseId": "jalesa-reynolds", "text": "New case added to the archive: Jalesa Chantell Reynolds (Scotland Neck, North Carolina, 2010), a missing persons case, sourced from The Charley Project."}, {"date": "2026-08-27", "caseId": "brown-family", "text": "New case added to the archive: Carolyn, Sheketah, Barry & Brandon Brown (Port St. Lucie, Florida, 1985), a missing persons case, sourced from The Charley Project and The Doe Network."}, {"date": "2026-08-27", "caseId": "anwar-green", "text": "New case added to the archive: Anwar Green (Newark, New Jersey, 2001), a missing persons case, sourced from The Charley Project."}, {"date": "2026-08-27", "caseId": "jahi-turner", "text": "New case added to the archive: Jahi Turner (San Diego, California, 2002), a missing persons case, sourced from KPBS's coverage of both the 2016 arrest and the 2018 mistrial and dismissal, and ABC7 Los Angeles."}, {"date": "2026-08-27", "caseId": "nakyla-williams", "text": "New case added to the archive: Nakyla Williams (Indianapolis, Indiana, 2021), a missing persons case, sourced from NewsNation, WTHR, and NBC News."}, {"date": "2026-08-27", "caseId": "kierra-coles", "text": "New case added to the archive: Kierra Coles (Chicago, Illinois, 2018), a missing persons case, sourced from CBS News Chicago, ABC News, and the Chicago Sun-Times."}, {"date": "2026-08-27", "caseId": "keeshae-jacobs", "text": "New case added to the archive: Keeshae Jacobs (Richmond, Virginia, 2016), a missing persons case, sourced from NBC News/Dateline, WWBT NBC12, and CBS News."}, {"date": "2026-08-27", "caseId": "asha-degree", "text": "New case added to the archive: Asha Degree (Shelby, North Carolina, 2000), a missing persons case, sourced from the FBI's official case appeal, ABC11 Raleigh-Durham, and CrimeOnline."}, {"date": "2026-08-27", "caseId": "relisha-rudd", "text": "New case added to the archive: Relisha Rudd (Washington, D.C., 2014), a missing persons case, sourced from the FBI's official case listing, the Metropolitan Police Department via Solve the Case, and WTOP News."}, {"date": "2026-08-27", "caseId": "manuel-ellis", "text": "New case added to the archive: Manuel Ellis (Tacoma, Washington, 2020), sourced from The Seattle Times, CNN, and NBC News's coverage of the officers' post-acquittal separation payments."}, {"date": "2026-08-27", "caseId": "daniel-prude", "text": "New case added to the archive: Daniel Prude (Rochester, New York, 2020), sourced from the New York Attorney General's official statement, CNN, and CBS News."}, {"date": "2026-08-27", "caseId": "miriam-carey", "text": "New case added to the archive: Miriam Carey (Washington, D.C., 2013), sourced from the DOJ/U.S. Attorney's Office's official statement, The Washington Post, and NPR."}, {"date": "2026-08-27", "caseId": "milton-hall", "text": "New case added to the archive: Milton Hall (Saginaw, Michigan, 2012), sourced from the ACLU of Michigan, the DOJ's own archived press release, and CNN's ongoing coverage."}, {"date": "2026-08-27", "caseId": "jonathan-ferrell", "text": "New case added to the archive: Jonathan Ferrell (Charlotte, North Carolina, 2013), sourced from NBC News's coverage of both the mistrial and the decision not to retry, and Slate."}, {"date": "2026-08-27", "caseId": "kenneth-chamberlain-sr", "text": "New case added to the archive: Kenneth Chamberlain Sr. (White Plains, New York, 2011), sourced from the DOJ's own closing statement, Democracy Now!, and ABC7 New York's coverage of the 2023 settlement."}, {"date": "2026-08-27", "caseId": "danroy-henry-jr", "text": "New case added to the archive: Danroy Henry Jr. (Thornwood, New York, 2010), sourced from ABC7 New York, CBS News, and a 2023 report on Westchester's independent re-review of the case."}, {"date": "2026-08-27", "caseId": "ezell-ford", "text": "New case added to the archive: Ezell Ford (Los Angeles, California, 2014), sourced from CBS News, the LA County DA's own charging decision letter, and the ACLU of Southern California."}, {"date": "2026-08-27", "caseId": "keith-lamont-scott", "text": "New case added to the archive: Keith Lamont Scott (Charlotte, North Carolina, 2016), sourced from CNN, ABC News, and the NAACP Legal Defense Fund."}, {"date": "2026-08-27", "caseId": "samuel-dubose", "text": "New case added to the archive: Samuel DuBose (Cincinnati, Ohio, 2015), sourced from NPR, NBC News, and Essence's coverage of the two mistrials and eventual dismissal."}, {"date": "2026-08-27", "caseId": "terence-crutcher", "text": "New case added to the archive: Terence Crutcher (Tulsa, Oklahoma, 2016), sourced from CNN, NBC News, and the NAACP Legal Defense Fund's analysis of the acquittal."}, {"date": "2026-08-27", "caseId": "sandra-bland", "text": "New case added to the archive: Sandra Bland (Prairie View, Texas, 2015), sourced from NBC News, The Texas Tribune, and Community Impact."}, {"date": "2026-08-27", "caseId": "john-crawford-iii", "text": "New case added to the archive: John Crawford III (Beavercreek, Ohio, 2014), sourced from NBC News, NPR, and Democracy Now!'s contemporaneous coverage."}, {"date": "2026-08-27", "caseId": "alton-sterling", "text": "New case added to the archive: Alton Sterling (Baton Rouge, Louisiana, 2016), sourced from Al Jazeera, NBC News, and the NAACP Legal Defense Fund's statement on the DOJ's decision."}, {"date": "2026-08-27", "caseId": "michael-brown", "text": "New case added to the archive: Michael Brown (Ferguson, Missouri, 2014), sourced from PBS NewsHour, NBC News, and CBS News's coverage of all three declined-charges decisions."}, {"date": "2026-08-27", "caseId": "stephon-clark", "text": "New case added to the archive: Stephon Clark (Sacramento, California, 2018), sourced from the California DOJ's own report, NPR, and NBC News."}, {"date": "2026-08-27", "caseId": "philando-castile", "text": "New case added to the archive: Philando Castile (Falcon Heights, Minnesota, 2016), sourced from CNN, NBC News, and MPR News's ongoing case coverage."}, {"date": "2026-08-27", "caseId": "tamir-rice", "text": "New case added to the archive: Tamir Rice (Cleveland, Ohio, 2014), sourced from NPR's coverage of both the 2015 grand jury decision and the 2020 DOJ decision, and NBC News's reporting on Officer Loehmann's 2017 firing."}, {"date": "2026-08-27", "caseId": "eric-garner", "text": "New case added to the archive: Eric Garner (Staten Island, New York, 2014), sourced from NBC News, NBC New York, and NY1's coverage of the NYPD disciplinary trial."}, {"date": "2026-08-27", "caseId": "rekia-boyd", "text": "New case added to the archive: Rekia Boyd (Chicago, Illinois, 2012), sourced from WTTW News, the Chicago Sun-Times, and Fox News/AP coverage of the case."}, {"date": "2026-08-27", "caseId": "breonna-taylor", "text": "New case added to the archive: Breonna Taylor (Louisville, Kentucky, 2020), sourced from the DOJ's own press release on the Brett Hankison conviction, Al Jazeera, and PBS NewsHour/AP coverage."}, {"date": "2026-08-27", "caseId": "freddie-gray", "text": "New case added to the archive: Freddie Gray (Baltimore, Maryland, 2015), sourced from the DOJ's archived statement declining federal prosecution, ABC News, and NPR."}, {"date": "2026-08-27", "caseId": "trayvon-martin", "text": "New case added to the archive: Trayvon Martin (Sanford, Florida, 2012), sourced from CNN, NPR, and Al Jazeera's trial coverage."}, {"date": "2026-08-27", "caseId": "sean-bell", "text": "New case added to the archive: Sean Bell (Queens, New York, 2006), sourced from NPR, ABC7 New York, and Democracy Now!'s coverage of the acquittal."}, {"date": "2026-08-27", "caseId": "amadou-diallo", "text": "New case added to the archive: Amadou Diallo (Bronx, New York, 1999), sourced from HISTORY, NY1, and EBSCO Research Starters."}, {"date": "2026-08-27", "caseId": "fred-hampton", "text": "New case added to the archive: Fred Hampton (Chicago, Illinois, 1969), sourced from Encyclopaedia Britannica, HISTORY, and The Real News Network's interview with the family's civil rights attorney."}, {"date": "2026-08-27", "caseId": "malcolm-x", "text": "New case added to the archive: Malcolm X (New York, New York, 1965), sourced from NPR, the Innocence Project via WilmerHale, and NBC News coverage of the 2021 exonerations."}, {"date": "2026-08-27", "caseId": "emmett-till", "text": "New case added to the archive: Emmett Till (Money, Mississippi, 1955), sourced from the DOJ's 2021 closing statement, CNN's coverage of the 2022 grand jury decision, and Mississippi Free Press."}, {"date": "2026-08-27", "caseId": "kierre-davies", "text": "New case added to the archive: Kierre Davies (Fargo, North Dakota, 2022), sourced from InForum and the City of Fargo's own press conference summary."}, {"date": "2026-08-27", "caseId": "julius-dubouse", "text": "New case added to the archive: Julius Dubouse (Anchorage, Alaska, 1998), sourced from Crime Solvers Central and the Anchorage Police Department's Cold Case Section page."}, {"date": "2026-08-26", "caseId": "quincy-booker", "text": "New case added to the archive: Quincy Booker (Albuquerque, New Mexico, 2011), sourced from the Albuquerque Police Department via Project Cold Case and a 2011 KOAT report."}, {"date": "2026-08-26", "caseId": "nacomie-freeman", "text": "New case added to the archive: Nacomie Freeman (Phoenix, Arizona, 2004), sourced from the Maricopa County Sheriff's Office via Project Cold Case and a 2004 Arizona Republic article."}, {"date": "2026-08-26", "caseId": "alexis-patterson", "text": "New case added to the archive: Alexis Patterson (Milwaukee, Wisconsin, 2002), sourced from the FBI's case listing, the Milwaukee Police Department via Solve the Case, and WUWM."}, {"date": "2026-08-26", "caseId": "frank-andrews", "text": "New case added to the archive: Frank Andrews (Lisman, Alabama, 1964), sourced from the DOJ's Civil Rights Division closing memorandum, PBS Frontline's \u201cUnresolved\u201d project, and Alabama Reflector."}, {"date": "2026-08-26", "caseId": "isaiah-henry", "text": "New case added to the archive: Isaiah Henry (Greensburg, Louisiana, 1954), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "john-earl-reese", "text": "New case added to the archive: John Earl Reese (Mayflower, Texas, 1955), sourced from the DOJ's Notice to Close File and The Dallas Morning News."}, {"date": "2026-08-26", "caseId": "james-earl-motley", "text": "New case added to the archive: James Earl Motley (Wetumpka, Alabama, 1966), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "thad-christian", "text": "New case added to the archive: Thad Christian (Anniston, Alabama, 1965), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "maceo-snipes", "text": "New case added to the archive: Maceo Snipes (Butler, Georgia, 1946), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the Georgia Civil Rights Cold Cases Project at Emory University. This case directly connects to Isaiah Nixon's case, documented in this archive as case #030 \u2014 both men were killed for voting-related activity in the same Georgia region two years apart."}, {"date": "2026-08-26", "caseId": "isaiah-nixon", "text": "Updated the case's unanswered questions to reference Maceo Snipes's case, newly added to this archive, which shares the same regional and thematic connection."}, {"date": "2026-08-26", "caseId": "herbert-lee", "text": "New case added to the archive: Herbert Lee (Liberty, Mississippi, 1961), sourced from the DOJ's Notice to Close File. This case directly connects to Louis Allen's case, documented in this archive as case #018 \u2014 Allen witnessed Lee's killing, later recanted his corroborating testimony to the FBI, and was himself murdered in 1964."}, {"date": "2026-08-26", "caseId": "louis-allen", "text": "Updated the case's unanswered questions to reference Herbert Lee's case, newly added to this archive, which Allen witnessed and later gave conflicting testimony about."}, {"date": "2026-08-26", "caseId": "samuel-younge-jr", "text": "New case added to the archive: Samuel Younge Jr. (Tuskegee, Alabama, 1966), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "isaiah-taylor", "text": "New case added to the archive: Isaiah Taylor (Ruleville, Mississippi, 1964), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "jimmie-lee-jackson", "text": "New case added to the archive: Jimmie Lee Jackson (Marion, Alabama, 1965), sourced from the DOJ's Notice to Close File. This case produced the only conviction the Emmett Till Act's cold case review process has generated since 2008, and is directly referenced in this archive's Cold Case Quiz."}, {"date": "2026-08-26", "caseId": "thomas-brewer", "text": "New case added to the archive: Dr. Thomas Brewer (Columbus, Georgia, 1956), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "ernest-jells", "text": "New case added to the archive: Ernest Jells (Clarksdale, Mississippi, 1963), sourced from the DOJ's 2010 Notice to Close File."}, {"date": "2026-08-26", "caseId": "benjamin-brown", "text": "New case added to the archive: Benjamin Brown (Jackson, Mississippi, 1967), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "larry-payne", "text": "New case added to the archive: Larry Payne (Memphis, Tennessee, 1968), sourced from the DOJ's Notice to Close File."}, {"date": "2026-08-26", "caseId": "joseph-dumas", "text": "New case added to the archive: Joseph Dumas (Perry, Florida, 1962), sourced from the DOJ's 2010 Notice to Close File."}, {"date": "2026-08-26", "caseId": "vincent-dahmon", "text": "New case added to the archive: Vincent Dahmon (Natchez, Mississippi, 1966), sourced from the DOJ's 2010 Notice to Close File. His killing occurred during the period of James Meredith's 1966 March Against Fear."}, {"date": "2026-08-26", "caseId": "ed-smith", "text": "New case added to the archive: Ed Smith (State Line, Mississippi, 1958), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's 2009 Notice to Close File."}, {"date": "2026-08-26", "caseId": "lamar-smith", "text": "New case added to the archive: Lamar Smith (Brookhaven, Mississippi, 1955), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the Equal Justice Initiative. His killing was cited in the NAACP's own 1955 pamphlet alongside the killings of Rev. George Lee and Emmett Till, both also documented in this archive."}, {"date": "2026-08-26", "caseId": "willie-countryman", "text": "New case added to the archive: Willie Countryman (Dawson, Georgia, 1958), sourced from the Georgia Civil Rights Cold Cases Project at Emory University and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-26", "caseId": "donald-raspberry", "text": "New case added to the archive: Donald Raspberry (Okolona, Mississippi, 1965), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's 2010 Notice to Close File."}, {"date": "2026-08-26", "caseId": "william-henry-lee", "text": "New case added to the archive: William Henry Lee (Goshen Springs, Mississippi, 1965), sourced from the DOJ's Civil Rights Division case file."}, {"date": "2026-08-26", "caseId": "charles-brown", "text": "New case added to the archive: Charles Brown (Benton, Mississippi, 1957), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's 2010 Notice to Close File."}, {"date": "2026-08-26", "caseId": "dan-carter-sanders", "text": "New case added to the archive: Dan Carter Sanders (Cleveland Township, North Carolina, 1946), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the DOJ's 2019 Notice to Close File."}, {"date": "2026-08-26", "caseId": "felix-hall", "text": "New case added to the archive: Felix Hall (Fort Benning, Georgia, 1941), sourced from The Washington Post's 2016 investigation and the U.S. Army's 2021 memorial plaque text. This remains the only known lynching to have occurred on a U.S. military base."}, {"date": "2026-08-26", "caseId": "leonard-mccowin", "text": "New case added to the archive: Leonard McCowin (Center, Texas, 1947), sourced from the Civil Rights Cold Case Records Review Board's official federal case file and Capital B News's 2025 investigative reporting."}, {"date": "2026-08-26", "caseId": "thomas-coleman", "text": "New case added to the archive: Thomas Coleman (Salt Lake City, Utah, 1866), sourced from the University of Utah's \u201cRacial Lynching in Utah\u201d and \u201cCentury of Black Mormons\u201d exhibits. This case is directly connected to William \u201cSam Joe\u201d Harvey's case, documented in this archive as case #061 \u2014 both men were killed in Salt Lake City, 17 years apart, and were jointly memorialized in a 2022 ceremony."}, {"date": "2026-08-26", "caseId": "william-harvey", "text": "New case added to the archive: William \u201cSam Joe\u201d Harvey (Salt Lake City, Utah, 1883), sourced from the University of Utah's Marriott Library exhibit on racial lynching in Utah and the Utah State Historical Society. This is the first Utah case documented in the archive."}, {"date": "2026-08-26", "caseId": "timothy-pettis", "text": "New case added to the archive: Timothy Pettis (Coos Bay, Oregon, 1924), sourced from Oregon Historical Quarterly and OPB's \u201cOregon Experience\u201d documentary. This case directly connects to Alonzo Tucker's case, documented in this archive as case #059 \u2014 both men were killed in the same Coos Bay waters, twenty-two years apart."}, {"date": "2026-08-26", "caseId": "alonzo-tucker", "text": "New case added to the archive: Alonzo Tucker (Coos Bay, Oregon, 1902), sourced from the Equal Justice Initiative's historical marker and the Oregon Remembrance Project. This is the first Oregon case documented in the archive, and remains the only documented lynching of a Black person in the state's history."}, {"date": "2026-08-26", "caseId": "clinton-melton", "text": "New case added to the archive: Clinton Melton (Glendora, Mississippi, 1955), sourced from the DOJ's Civil Rights Division case file and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-26", "caseId": "carol-jenkins", "text": "New case added to the archive: Carol Jenkins (Martinsville, Indiana, 1968), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and the African American Registry."}, {"date": "2026-08-26", "caseId": "john-wesley-wilder", "text": "New case added to the archive: John Wesley Wilder (Ruston, Louisiana, 1965), sourced from the DOJ's 2011 Notice to Close File and Type Investigations' 2023 investigative report."}, {"date": "2026-08-26", "caseId": "darrion-carrington", "text": "New case added to the archive: Darrion \u201cPritz\u201d Carrington (Boston, Massachusetts, 2008), sourced from the Boston Police Department's official unsolved homicides list and Boston 25 News. This is the first Massachusetts case documented in the archive."}, {"date": "2026-08-26", "caseId": "jeffery-zolliecoffer", "text": "New case added to the archive: Jeffery \u201cJo Jo\u201d Zolliecoffer (Waterloo, Iowa, 1989), sourced from Iowa Cold Cases, the Iowa Attorney General's cold case files, and a contemporaneous news photograph from the 2015 \u201cGone Cold: Exploring Iowa's Unsolved Murders\u201d statewide newspaper project."}, {"date": "2026-08-25", "caseId": "samuel-johnson", "text": "New case added to the archive: Samuel Johnson, known as \u201cMingo Jack\u201d (Eatontown, New Jersey, 1886), sourced from research by local historian Gary Saretzky, published by the New Jersey Social Justice Remembrance Committee. This is the first New Jersey case documented in the archive."}, {"date": "2026-08-25", "caseId": "george-white", "text": "New case added to the archive: George White (Wilmington, Delaware, 1903), sourced from the Delaware Public Archives' official historical marker and the Equal Justice Initiative. This is the first Delaware case documented in the archive, and is generally regarded as the only documented lynching in the state's history."}, {"date": "2026-08-25", "caseId": "preston-porter-jr", "text": "New case added to the archive: Preston Porter Jr. (Limon, Colorado, 1900), sourced from History Colorado and the Colorado Encyclopedia. This is the first Colorado case documented in the archive."}, {"date": "2026-08-25", "caseId": "james-t-scott", "text": "New case added to the archive: James T. Scott (Columbia, Missouri, 1923), sourced from the State Historical Society of Missouri. This is the first Missouri case documented in the archive."}, {"date": "2026-08-25", "caseId": "george-tompkins", "text": "New case added to the archive: George Tompkins (Indianapolis, Indiana, 1922), sourced from CNN and Wikipedia. This is the first Indiana case documented in the archive; his death certificate was formally corrected from suicide to homicide in 2022."}, {"date": "2026-08-25", "caseId": "tulsa-race-massacre", "text": "New case added to the archive: Tulsa Race Massacre (Tulsa, Oklahoma, 1921), sourced from the DOJ Civil Rights Division's January 2025 review and evaluation, released under the Emmett Till Unsolved Civil Rights Crime Act. This is the first Oklahoma case documented in the archive, and represents an estimated 75 to 300 victims rather than a single named individual."}, {"date": "2026-08-25", "caseId": "john-henry-james", "text": "New case added to the archive: John Henry James (Charlottesville, Virginia, 1898), sourced from Encyclopedia Virginia. This is the first Virginia case documented in the archive."}, {"date": "2026-08-25", "caseId": "duluth-lynchings", "text": "New case added to the archive: Elias Clayton, Elmer Jackson & Isaac McGhie (Duluth, Minnesota, 1920), sourced from the Minnesota Historical Society and Smithsonian Magazine. This is the first Minnesota case documented in the archive."}, {"date": "2026-08-25", "caseId": "wade-hampton", "text": "New case added to the archive: Wade Hampton (Rock Springs, Wyoming, 1917), sourced from WyoHistory.org's account drawn from the original coroner's inquest transcript. This is the first Wyoming case documented in the archive."}, {"date": "2026-08-25", "caseId": "whitfield-and-whitney", "text": "New case added to the archive: Ed Whitfield & Earl Whitney (Chapmanville, West Virginia, 1919), sourced from the West Virginia Encyclopedia and The Clio. This is the first West Virginia case documented in the archive."}, {"date": "2026-08-25", "caseId": "will-brown", "text": "New case added to the archive: Will Brown (Omaha, Nebraska, 1919), sourced from History Nebraska (the state historical society) and PBS's American Experience. This is the first Nebraska case documented in the archive."}, {"date": "2026-08-25", "caseId": "lester-mitchell", "text": "New case added to the archive: Lester Mitchell (Dayton, Ohio, 1966), sourced from the Dayton Daily News and BlackPast.org. This is the first Ohio case documented in the archive."}, {"date": "2026-08-25", "caseId": "timothy-thomas", "text": "New case added to the archive: Timothy Thomas (Cincinnati, Ohio, 2001), sourced from The Washington Post and the IAED Journal's case retrospective."}, {"date": "2026-08-25", "caseId": "matthew-williams", "text": "New case added to the archive: Matthew Williams (Salisbury, Maryland, 1931), sourced from the Maryland State Archives and the International Center for Transitional Justice. This is the first Maryland case documented in the archive."}, {"date": "2026-08-25", "caseId": "carl-hampton", "text": "New case added to the archive: Carl Hampton (Houston, Texas, 1970), sourced from the Houston Chronicle and Liberation News."}, {"date": "2026-08-25", "caseId": "james-powell", "text": "New case added to the archive: James Powell (Manhattan, New York, 1964), sourced from extensive contemporaneous and historical reporting on the Harlem riot of 1964. This is the first New York case documented in the archive."}, {"date": "2026-08-25", "caseId": "rogers-hamilton", "text": "New case added to the archive: Rogers Hamilton (Hayneville, Alabama, 1957), sourced from the DOJ's 2016 Notice to Close File and Alabama Reporter's 2025 investigative follow-up."}, {"date": "2026-08-25", "caseId": "eddie-cook", "text": "New case added to the archive: Eddie Cook (Detroit, Michigan, 1965), sourced from the DOJ's 2020 Notice to Close File and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary. This is the first Michigan case documented in the archive."}, {"date": "2026-08-25", "caseId": "lee-edward-culbreath", "text": "New case added to the archive: Lee Edward Culbreath (Portland, Arkansas, 1965), sourced from the DOJ's 2019 Notice to Close File and the Encyclopedia of Arkansas."}, {"date": "2026-08-25", "caseId": "elbert-williams", "text": "New case added to the archive: Elbert Williams (Brownsville, Tennessee, 1940), sourced from the DOJ's Civil Rights Division case file and BlackPast.org. This is the first Tennessee case documented in the archive, and the earliest case tied to formal NAACP civil rights organizing."}, {"date": "2026-08-25", "caseId": "henry-marrow", "text": "New case added to the archive: Henry \u201cDickie\u201d Marrow Jr. (Oxford, North Carolina, 1970), sourced from the DOJ's Civil Rights Division case file and the North Carolina Department of Natural and Cultural Resources. This is the first North Carolina case documented in the archive."}, {"date": "2026-08-25", "caseId": "donna-ann-reason", "text": "New case added to the archive: Donna Ann Reason (Chester, Pennsylvania, 1970), sourced from the DOJ's February 2025 Notice to Close File and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary. This is the first Pennsylvania case documented in the archive."}, {"date": "2026-08-25", "caseId": "isaiah-nixon", "text": "New case added to the archive: Isaiah Nixon (Alston, Georgia, 1948), sourced from the Georgia Civil Rights Cold Cases Project at Emory University and the federal Civil Rights Cold Case Records Review Board. This is the first Georgia case documented in the archive."}, {"date": "2026-08-25", "caseId": "orangeburg-massacre", "text": "New case added to the archive: Samuel Hammond, Henry Smith & Delano Middleton (Orangeburg, South Carolina, 1968), sourced from BlackPast.org and the Lowcountry Digital History Initiative. This is the first South Carolina case documented in the archive."}, {"date": "2026-08-24", "caseId": "frank-morris", "text": "Expanded the case summary with detail from the DOJ's Notice to Close File: the file names four Silver Dollar Group members \u2014 E.D. Morace, Tommie Lee Jones, Thor Lee Torgersen, and James Lee Scarborough \u2014 identified by FBI informants, and links this case to the same Klan cell as Wharlest Jackson Sr. and Joseph Edwards. Previously this connection was not named."}, {"date": "2026-08-24", "caseId": "john-allen", "text": "New case added to the archive: John Allen (Des Moines, Iowa, 1864), sourced from Iowa Unsolved Murders: Historic Cases, drawing on contemporary newspaper accounts and an 1898 county history. This is the first Iowa case documented in the archive."}, {"date": "2026-08-24", "caseId": "nicholas-a-brown", "text": "New case added to the archive: Nicholas A. Brown (Davenport, Iowa, 2021), sourced from the Iowa Attorney General's office and the Quad-City Times."}, {"date": "2026-08-24", "caseId": "brandon-mcclelland", "text": "New case added to the archive: Brandon McClelland (Paris, Texas, 2008), sourced from contemporaneous news reporting and court records. This is currently the most recent case documented in the archive after Alonzo Brooks (2004), filling a gap in the archive's 1970s\u20132000s coverage."}, {"date": "2026-08-24", "caseId": "claude-neal", "text": "New case added to the archive: Claude Neal (Greenwood, Florida, 1934), sourced from the DOJ's Civil Rights Division case file and Explore Southern History. This is currently the earliest case documented in the archive."}, {"date": "2026-08-24", "caseId": "samuel-oquinn", "text": "New case added to the archive: Samuel O'Quinn (Centreville, Mississippi, 1959), sourced from the DOJ's 2012 Notice to Close File and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-24", "caseId": "willie-edwards-jr", "text": "New case added to the archive: Willie Edwards Jr. (Montgomery, Alabama, 1957), sourced from the DOJ's Civil Rights Division case file and its 2013 Notice to Close File."}, {"date": "2026-08-24", "caseId": "isadore-banks", "text": "New case added to the archive: Isadore Banks (Marion, Arkansas, 1954), sourced from the DOJ's Civil Rights Division case file and the Encyclopedia of Arkansas."}, {"date": "2026-08-24", "caseId": "mack-charles-parker", "text": "New case added to the archive: Mack Charles Parker (Poplarville, Mississippi, 1959), sourced from PBS FRONTLINE's \u201cUn(re)solved\u201d case summary and Mississippi Today."}, {"date": "2026-08-24", "caseId": "joseph-edwards", "text": "New case added to the archive: Joseph Edwards (Vidalia, Louisiana, 1964), sourced from the DOJ's Civil Rights Division case file and its 2013 Notice to Close File."}, {"date": "2026-08-24", "caseId": "louis-allen", "text": "New case added to the archive: Louis Allen (Liberty, Mississippi, 1964), sourced from the DOJ's Civil Rights Division case file and its 2015 Notice to Close File."}, {"date": "2026-08-24", "caseId": "oneal-moore", "text": "New case added to the archive: Oneal Moore (Varnado, Louisiana, 1965), sourced from the DOJ's Civil Rights Division case file and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-24", "caseId": "clifton-walker", "text": "New case added to the archive: Clifton Walker (Woodville, Mississippi, 1964), sourced from the DOJ's Civil Rights Division case file and its 2013 Notice to Close File."}, {"date": "2026-08-24", "caseId": "johnnie-mae-chappell", "text": "New case added to the archive: Johnnie Mae Chappell (Jacksonville, Florida, 1964), sourced from the DOJ's 2014 Notice to Close File and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-24", "caseId": "wharlest-jackson-sr", "text": "New case added to the archive: Wharlest Jackson Sr. (Natchez, Mississippi, 1967), sourced from the DOJ's Civil Rights Division case file and PBS FRONTLINE's \u201cAmerican Reckoning.\u201d"}, {"date": "2026-08-24", "caseId": "frank-morris", "text": "New case added to the archive: Frank Morris (Ferriday, Louisiana, 1964), sourced from the DOJ's Civil Rights Division case file and PBS FRONTLINE's \u201cUn(re)solved\u201d case summary."}, {"date": "2026-08-24", "caseId": "george-lee", "text": "New case added to the archive: Rev. George Lee (Belzoni, Mississippi, 1955), sourced from the DOJ's Civil Rights Division case file and the Southern Poverty Law Center's case summary."}, {"date": "2026-08-22", "caseId": "harry-and-harriette-moore", "text": "Added a verified, public-domain photograph of Harry T. Moore, sourced directly from the State Archives of Florida (Florida Memory). No verified photograph of Harriette Moore alone has been located yet."}, {"date": "2026-08-21", "caseId": "darlenia-denise-johnson", "text": "Corrected the location of her summer job, previously conflated with her home neighborhood. She lived in Congress Heights; she was on her way to work at the Oxon Hill Recreation Center, a separate location, when she was abducted."}, {"date": "2026-08-21", "caseId": "brenda-faye-crockett", "text": "Added her exact disappearance date, July 27, 1971, previously recorded only as \u201cJuly 1971.\u201d"}, {"date": "2026-08-21", "caseId": "brenda-denise-woodard", "text": "Added her exact abduction date and circumstances \u2014 the night of November 15, 1971, after leaving night school \u2014 which were not previously on record."}, {"date": "2026-08-21", "caseId": "harry-and-harriette-moore", "text": "Added that the FBI reviewed the case again in 2008 under the Emmett Till Unsolved Civil Rights Crime Act, and that the DOJ formally closed the file in 2011."}, {"date": "2026-08-21", "caseId": "hattie-debardelaben", "text": "Added the names of the three federal officers present at the search, previously described only generically as \u201cthree federal officers.\u201d Also added that an undertaker reportedly found signs consistent with a broken neck, contradicting the officially recorded cause of death (heart attack)."}, {"date": "2026-08-21", "caseId": "alberta-jones", "text": "Corrected case status. This file previously stated the DOJ's cold-case review \u201cremains open\u201d; the DOJ in fact formally closed the file in August 2023 without identifying a suspect. Updated the summary accordingly."}, {"date": "2026-08-21", "caseId": "alonzo-brooks", "text": "Corrected status from Cold Case to Unsolved to reflect the active federal hate-crime investigation. Added the exact body-recovery date, May 1, 2004, previously recorded only as \u201cabout a month later.\u201d Added a verified FBI photograph."}, {"date": "2026-08-21", "caseId": "diamond-and-tionda-bradley", "text": "Added verified FBI photographs of both sisters, and the FBI's specific published reward amount ($10,000), previously described only as \u201ca reward.\u201d"}];